[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/repo/survey-2025> ;
            sh:resultMessage "cdi:allowsDuplicates indicates whether the collection permits duplicate members" ;
            sh:resultPath cdi:allowsDuplicates ;
            sh:resultSeverity sh:Info ;
            sh:sourceConstraintComponent sh:DatatypeConstraintComponent ;
